import{_ as a,o as d,c as t,a2 as s}from"./chunks/framework.BV2xZELn.js";const m=JSON.parse('{"title":"Model Manager Plugin","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/more/model-manager.md","filePath":"plugins/more/model-manager.md","lastUpdated":null}'),o={name:"plugins/more/model-manager.md"};function i(l,e,n,r,c,h){return d(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="model-manager-plugin" tabindex="-1">Model Manager Plugin <a class="header-anchor" href="#model-manager-plugin" aria-label="Permalink to &quot;Model Manager Plugin&quot;">​</a></h1><p>Keeps AI models in one folder of the app and imports them from the user&#39;s own files. The <code>llm</code> and <code>speechOffline</code> plugins read their models from here.</p><h2 id="plugin-name" tabindex="-1">Plugin Name <a class="header-anchor" href="#plugin-name" aria-label="Permalink to &quot;Plugin Name&quot;">​</a></h2><p><code>modelManager</code></p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;app support dir&gt;/models/&lt;kind&gt;/&lt;id&gt;/   the files of one model</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>kind</code> groups models by use: <code>llm</code>, <code>stt</code>, <code>tts</code>... (lowercase letters, digits, <code>_</code>). A model is a folder, because some are several files (a Whisper encoder, decoder and tokens; a GGUF and its multimodal projector; a voice with its <code>espeak-ng-data</code> folder).</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Args</th><th>Returns</th></tr></thead><tbody><tr><td><code>import</code></td><td><code>kind</code>, <code>name?</code>, <code>extensions?</code>, <code>extract?</code> (default <code>true</code>)</td><td><code>{ imported, model }</code> or <code>{ imported: false, reason: &#39;cancelled&#39; }</code></td></tr><tr><td><code>list</code></td><td><code>kind?</code></td><td><code>{ models }</code></td></tr><tr><td><code>get</code></td><td><code>id</code></td><td><code>{ found, model? }</code></td></tr><tr><td><code>rename</code></td><td><code>id</code>, <code>name</code></td><td><code>{ model }</code></td></tr><tr><td><code>remove</code></td><td><code>id</code></td><td><code>{ removed }</code></td></tr><tr><td><code>getInfo</code></td><td>—</td><td><code>{ root, count, sizeBytes }</code></td></tr></tbody></table><p><code>model</code> is <code>{ id, kind, name, dir, files: [{ name, path, size }], directories, sizeBytes, createdAt }</code>.</p><p><code>import</code> opens the system file picker (several files allowed). The files, or an archive (<code>.zip</code>, <code>.tar</code>, <code>.tar.gz</code>, <code>.tar.bz2</code>, <code>.tar.xz</code>), become one model. Archives are unpacked and a single top-level folder is flattened. No permission is needed. The picker copies each file into the app&#39;s cache, which is on the same storage as the models folder, so the move is instant even for a multi-gigabyte model.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><ul><li><code>modelManager.progress</code> — <code>{ id, stage: start|moving|extracting|done, file?, index?, files? }</code></li></ul><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>The plugins that run models accept only paths inside this folder (<code>..</code> and links are resolved before the check).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NativeSDK.modelManager.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ kind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;llm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NativeSDK.llm.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ modelId: model.id });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><p>Source: <a href="https://github.com/legionir/sweetmelon/blob/main/lib/plugins/model_manager/README.md" target="_blank" rel="noreferrer"><code>lib/plugins/model_manager/README.md</code></a></p>`,19)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
